html:
{% set company = frappe.get_doc("Company", doc.company) if doc.company else None %}

{% if letter_head %}
	<div class="letter-head">{{ letter_head }}</div>
{% endif %}

<style>
    @import url('https://fonts.googleapis.com/css2?family=Sarabun:wght@400;600;700&display=swap');

    * {
        font-family: 'Sarabun', sans-serif;
        box-sizing: border-box;
    }

    body {
		margin-bottom: 0mm !important;
		padding: 0px !important;
	}

    .print-format {
        font-size: 10pt;
        color: #333;
        line-height: 1.4;
        width: 100%;
        padding: 5px !important;
    }

    .print-format td {
        padding: 3px !important;
    }

    .letter-head {
			margin-top: 0px !important;
			padding-left: 10px !important;
			margin-bottom: 15px !important;
	}

    table {
        border-collapse: collapse;
        width: 100%;
    }

    .header-table {
        border-bottom: 2px solid #333;
        margin-bottom: 5px;
    }

    .header-table td {
        padding: 3px 0;
        vertical-align: top;
    }

    .company-name {
        font-size: 18pt;
        font-weight: 700;
        color: #000;
        margin: 0;
    }

    .doc-title {
        font-size: 14pt;
        font-weight: 600;
        color: #333;
        margin: 3px 0 0 0;
    }

    .doc-number {
        font-size: 12pt;
        font-weight: 700;
        color: #000;
    }

    .doc-date {
        font-size: 9pt;
        color: #666;
    }

    .section-title {
        font-size: 10pt;
        font-weight: 700;
        color: #000;
        border-bottom: 1px solid #999;
        padding: 2px 0;
        margin-bottom: 3px;
    }

    .info-table {
        margin-bottom: 1px;
    }

    .info-table td {
        padding: 1px 1px;
        vertical-align: top;
    }

    .info-label {
        font-weight: 600;
        color: #555;
        width: 100px;
        white-space: nowrap;
    }

    .info-value {
        color: #000;
    }

    .highlight {
        font-weight: 700;
        font-size: 11pt;
    }

    .two-col-table {
        margin-bottom: 4px;
    }

    .two-col-table > tbody > tr > td {
        width: 50%;
        vertical-align: top;
        padding-right: 5px;
    }

    .two-col-table > tbody > tr > td:last-child {
        padding-right: 0;
        padding-left: 5px;
    }

    .data-table {
        font-size: 9pt;
        margin-bottom: 10px;
    }

    .data-table th {
        background: #f0f0f0;
        border: 1px solid #999;
        padding: 6px 4px;
        text-align: left;
        font-weight: 600;
        color: #333;
    }

    .data-table td {
        border: 1px solid #ccc;
        padding: 5px 4px;
    }

    .data-table tbody tr:nth-child(even) {
        background: #fafafa;
    }

    .text-right { text-align: right; }
    .text-center { text-align: center; }

    .totals-table {
        margin-top: 15px;
        border-top: 1px solid #999;
        padding-top: 10px;
    }

    .totals-table td {
        padding: 3px 5px;
    }

    .total-label {
        text-align: right;
        color: #555;
        font-size: 10pt;
    }

    .total-value {
        text-align: right;
        font-weight: 600;
        font-size: 10pt;
        width: 120px;
    }

    .grand-total td {
        font-size: 12pt;
        font-weight: 700;
        border-top: 2px solid #333;
        padding-top: 8px;
    }

    .grand-total .total-value {
        color: #000;
        font-size: 12pt;
    }

    .notes-box {
        background: #f5f5f5;
        border: 1px solid #ddd;
        padding: 8px;
        margin-bottom: 8px;
    }

    .notes-label {
        font-weight: 600;
        color: #333;
        margin-bottom: 3px;
    }

    .sig-table {
        margin-top: 30px;
    }

    .sig-table td {
        width: 50%;
        text-align: center;
        padding: 0 20px;
    }

    .sig-line {
        border-top: 1px solid #333;
        margin-top: 40px;
        padding-top: 5px;
        font-size: 9pt;
    }

    .sig-date {
        font-size: 8pt;
        color: #666;
        margin-top: 3px;
    }

    .footer {
        margin-top: 20px;
        padding-top: 10px;
        border-top: 1px solid #ccc;
        text-align: center;
        font-size: 8pt;
        color: #888;
    }

    .company-address {
        font-size: 8pt;
        color: #666;
        margin-top: 3px;
    }
</style>

<div class="print-format">
    <!-- Header -->
    <table class="header-table">
        <tr>
            <td style="width: 60%;">
                <div class="company-name">{{ company.company_name if company else "ศูนย์บริการรถ" }}</div>
                <div class="doc-title">ใบสั่งงานบริการ / Service Order</div>
                {% if company and company.company_address %}
                <div class="company-address">{{ company.company_address }}</div>
                {% endif %}
            </td>
            <td style="width: 40%; text-align: right;">
                <div class="doc-number">{{ doc.name }}</div>
                <div class="doc-date">{{ frappe.utils.format_datetime(doc.service_date, "dd/MM/yyyy HH:mm") }}</div>
            </td>
        </tr>
    </table>

    <!-- Customer & Vehicle Info -->
    <table class="two-col-table">
        <tr>
            <td style="width: 65%">
                <div class="section-title">ข้อมูลลูกค้า</div>
                <table class="info-table">
                    <tr>
                        <td class="info-label">ลูกค้า:</td>
                        <td class="info-value">{{ doc.customer }}</td>
                    </tr>

                    {% if doc.address_display %}
                    <tr>
                        <td class="info-label">ที่อยู่:</td>
                        <td class="info-value">{{ doc.address_display | replace('<br>', ', ') | striptags | replace('
', ' ') | replace('  ', ' ') | replace(', , ', ', ') | replace(', ,', ',') | trim | trim(', ') }}</td>
                    </tr>
                    {% endif %}
                    {% if doc.tax_id %}
                    <tr>
                        <td class="info-label">TAX ID:</td>
                        <td class="info-value">{{ doc.tax_id }}</td>
                    </tr>
                    {% endif %}
                                        {% if doc.contact_person %}
                    <tr>
                        <td class="info-label">ผู้ติดต่อ:</td>
                        <td class="info-value">{{ doc.contact_person }}</td>
                    </tr>
                    {% endif %}
                    {% if doc.contact_number %}
                    <tr>
                        <td class="info-label">โทรศัพท์:</td>
                        <td class="info-value">{{ doc.contact_number }}</td>
                    </tr>
                    {% endif %}
                    {% if doc.email %}
                    <tr>
                        <td class="info-label">อีเมล:</td>
                        <td class="info-value">{{ doc.email }}</td>
                    </tr>
                    {% endif %}
                </table>
            </td>
            <td>
                <div class="section-title">ข้อมูลรถ</div>
                <table class="info-table">
                    <tr>
                        <td class="info-label">ทะเบียนรถ:</td>
                        <td class="info-value highlight">{{ doc.vehicle }}</td>
                    </tr>
                    {% if doc.brand %}
                    <tr>
                        <td class="info-label">ยี่ห้อ:</td>
                        <td class="info-value">{{ doc.brand }}</td>
                    </tr>
                    {% endif %}
                    {% if doc.model %}
                    <tr>
                        <td class="info-label">รุ่น:</td>
                        <td class="info-value">{{ doc.model }}</td>
                    </tr>
                    {% endif %}
                    {% if doc.vehicle_type %}
                    <tr>
                        <td class="info-label">ประเภท:</td>
                        <td class="info-value">{{ doc.vehicle_type }}</td>
                    </tr>
                    {% endif %}
                    {% if doc.vin_number %}
                    <tr>
                        <td class="info-label">เลขตัวถัง:</td>
                        <td class="info-value">{{ doc.vin_number }}</td>
                    </tr>
                    {% endif %}
                    {% if doc.engine_number %}
                    <tr>
                        <td class="info-label">เลขเครื่อง:</td>
                        <td class="info-value">{{ doc.engine_number }}</td>
                    </tr>
                    {% endif %}
                    {% if doc.current_mileage %}
                    <tr>
                        <td class="info-label">เลขไมล์:</td>
                        <td class="info-value">{{ "{:,.0f}".format(doc.current_mileage) }} กม.</td>
                    </tr>
                    {% endif %}
                    {% if doc.fuel_level_in or doc.fuel_level_out %}
                    <tr>
                        <td class="info-label">น้ำมัน:</td>
                        <td class="info-value">เข้า: {{ doc.fuel_level_in or '-' }} | ออก: {{ doc.fuel_level_out or '-' }}</td>
                    </tr>
                    {% endif %}
                </table>
            </td>
        </tr>
    </table>

    <!-- Technician -->
    {% if doc.received_by or doc.technician or doc.technician_2 or doc.technician_3 or doc.technician_4 %}
    <div class="section-title">ช่างและพนักงาน</div>
    <table class="info-table">
        {% if doc.received_by %}
        <tr>
            <td class="info-label">รับรถโดย:</td>
            <td class="info-value">{{ frappe.db.get_value("User", doc.received_by, "full_name") or doc.received_by }}</td>
        </tr>
        {% endif %}
        {% set technicians = [] %}
        {% if doc.technician %}{% set _ = technicians.append(frappe.db.get_value("User", doc.technician, "full_name") or doc.technician) %}{% endif %}
        {% if doc.technician_2 %}{% set _ = technicians.append(frappe.db.get_value("User", doc.technician_2, "full_name") or doc.technician_2) %}{% endif %}
        {% if doc.technician_3 %}{% set _ = technicians.append(frappe.db.get_value("User", doc.technician_3, "full_name") or doc.technician_3) %}{% endif %}
        {% if doc.technician_4 %}{% set _ = technicians.append(frappe.db.get_value("User", doc.technician_4, "full_name") or doc.technician_4) %}{% endif %}
        {% if technicians %}
        <tr>
            <td class="info-label">ช่าง:</td>
            <td class="info-value">{{ technicians | join(', ') }}</td>
        </tr>
        {% endif %}
    </table>
    {% endif %}

    <!-- Service Types -->
    {% if doc.service_types %}
    <div class="section-title">ประเภทบริการ</div>
    <table class="data-table">
        <thead>
            <tr>
                <th style="width: 5%;">#</th>
                <th style="width: 80%;">ประเภทบริการ</th>
                <th style="width: 15%;" class="text-right">ค่าแรง</th>
            </tr>
        </thead>
        <tbody>
            {% for item in doc.service_types %}
            <tr>
                <td class="text-center">{{ loop.index }}</td>
                <td>
                    <div style="font-weight: 600;">{{ item.service_type }}</div>
                    {% if item.repair_position or item.repair_cause or item.remark %}
                    <div style="font-size: 8pt; color: #666; margin-top: 3px;">
                        {% if item.repair_position %}ตำแหน่ง: {{ item.repair_position }}{% endif %}
                        {% if item.repair_cause %}{% if item.repair_position %} | {% endif %}สาเหตุ: {{ item.repair_cause }}{% endif %}
                        {% if item.remark %}{% if item.repair_position or item.repair_cause %} | {% endif %}หมายเหตุ: {{ item.remark }}{% endif %}
                    </div>
                    {% endif %}
                </td>
                <td class="text-right">{{ "{:,.2f}".format(item.labor_charges or 0) }}</td>
            </tr>
            {% endfor %}
        </tbody>
        <tfoot>
            <tr>
                <td colspan="2" class="text-right" style="font-weight: 700; border-top: 1px solid #999; padding-top: 4px;">รวมค่าแรง:</td>
                <td class="text-right" style="font-weight: 700; border-top: 1px solid #999; padding-top: 4px;">{{ "{:,.2f}".format(doc.labor_charges or 0) }}</td>
            </tr>
        </tfoot>
    </table>
    {% endif %}

    <!-- Service Items -->
    {% if doc.service_items %}
    <div class="section-title">อะไหล่และวัสดุ</div>
    <table class="data-table">
        <thead>
            <tr>
                <th style="width: 5%;">#</th>
                <th style="width: 15%;">รหัส</th>
                <th style="width: 30%;">รายการ</th>
                <th style="width: 12%;" class="text-center">จำนวน</th>
                <th style="width: 8%;" class="text-center">หน่วย</th>
                <th style="width: 15%;" class="text-right">ราคา/หน่วย</th>
                <th style="width: 15%;" class="text-right">จำนวนเงิน</th>
            </tr>
        </thead>
        <tbody>
            {% for item in doc.service_items %}
            <tr>
                <td class="text-center">{{ loop.index }}</td>
                <td>{{ item.item_code }}</td>
                <td>{{ item.item_name or item.item_code }}</td>
                <td class="text-center">{{ "{:.2f}".format(item.qty or 0) }}</td>
                <td class="text-center">{{ item.uom or '-' }}</td>
                <td class="text-right">{{ "{:,.2f}".format(item.rate or 0) }}</td>
                <td class="text-right">{{ "{:,.2f}".format(item.amount or 0) }}</td>
            </tr>
            {% endfor %}
        </tbody>
        <tfoot>
            <tr>
                <td colspan="6" class="text-right" style="font-weight: 700; border-top: 1px solid #999; padding-top: 4px;">รวมค่าอะไหล่:</td>
                <td class="text-right" style="font-weight: 700; border-top: 1px solid #999; padding-top: 4px;">{{ "{:,.2f}".format(doc.total_parts_amount or 0) }}</td>
            </tr>
        </tfoot>
    </table>
    {% endif %}

    <!-- Totals -->
    <table class="totals-table">
        {% if doc.discount_amount %}
        <tr>
            <td class="total-label">ส่วนลด:</td>
            <td class="total-value">-{{ "{:,.2f}".format(doc.discount_amount) }}</td>
        </tr>
        {% endif %}
        {% if doc.tax_amount %}
        <tr>
            <td class="total-label">ภาษี:</td>
            <td class="total-value">{{ "{:,.2f}".format(doc.tax_amount) }}</td>
        </tr>
        {% endif %}
        <tr class="grand-total">
            <td class="total-label">ยอดรวมทั้งหมด:</td>
            <td class="total-value">{{ "{:,.2f}".format(doc.total_amount or 0) }} บาท</td>
        </tr>
    </table>

    <!-- Customer Complaints -->
    {% if doc.customer_complaints %}
    <div class="notes-box" style="margin-top: 15px;">
        <div class="notes-label">อาการที่แจ้ง:</div>
        <div>{{ doc.customer_complaints|safe }}</div>
    </div>
    {% endif %}

    <!-- Notes -->
    {% if doc.service_notes or doc.technician_remarks or doc.recommendations %}
    <div class="section-title" style="margin-top: 15px;">หมายเหตุ</div>
    {% if doc.service_notes %}
    <div class="notes-box">
        <div class="notes-label">บันทึกการบริการ:</div>
        <div>{{ doc.service_notes|safe }}</div>
    </div>
    {% endif %}
    {% if doc.technician_remarks %}
    <div class="notes-box">
        <div class="notes-label">คำแนะนำจากช่าง:</div>
        <div>{{ doc.technician_remarks|safe }}</div>
    </div>
    {% endif %}
    {% if doc.recommendations %}
    <div class="notes-box">
        <div class="notes-label">คำแนะนำเพิ่มเติม:</div>
        <div>{{ doc.recommendations|safe }}</div>
    </div>
    {% endif %}
    {% endif %}

    <!-- Signatures -->
    <table class="sig-table">
        <tr>
            <td>
                <div class="sig-line">ช่างผู้รับผิดชอบ</div>
                <div class="sig-date">วันที่: _____/_____/_________</div>
            </td>
            <td>
                <div class="sig-line">ลูกค้า/ผู้รับมอบ</div>
                <div class="sig-date">วันที่: _____/_____/_________</div>
            </td>
        </tr>
    </table>

    <!-- Footer -->
    <div class="footer">
        <div>กรุณาตรวจสอบรายการและรับรถภายใน 7 วัน</div>
        <div>Truck Service Center System</div>
    </div>
</div>
